{
  "$id": "https://app.tradeverifyd.example/templates/urn:tradeverifyd:template:iti-credential",
  "title": "Intent To Import Credential Schema",
  "description": "Schema for Intent To Import verifiable credentials containing trade documentation for US Customs submission",
  "type": "object",
  "properties": {
    "@context": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "JSON-LD context for the credential"
    },
    "type": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Credential type array"
    },
    "issuer": {
      "type": "string",
      "description": "DID of the credential issuer"
    },
    "credentialSubject": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "description": "Subject identifier"
        },
        "type": {
          "type": "string",
          "enum": [
            "ITI"
          ]
        },
        "shipment_id": {
          "type": "string",
          "description": "Associated shipment ID"
        },
        "customs_entry_number": {
          "type": "string",
          "description": "CBP entry number"
        },
        "importer": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string"
            },
            "address": {
              "type": "string"
            },
            "ein": {
              "type": "string"
            }
          },
          "required": [
            "name",
            "address"
          ]
        },
        "products": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "description": {
                "type": "string"
              },
              "hs_code": {
                "type": "string"
              },
              "quantity": {
                "type": "number"
              },
              "value": {
                "type": "number"
              }
            },
            "required": [
              "description",
              "hs_code",
              "quantity",
              "value"
            ]
          }
        }
      },
      "required": [
        "id",
        "type",
        "shipment_id",
        "importer",
        "products"
      ]
    }
  },
  "additionalProperties": false,
  "required": [
    "@context",
    "type",
    "issuer",
    "credentialSubject"
  ],
  "example": "Example ITI credential structure for electronics import"
}
